<?php
defined('ABSPATH') || exit;

/** MCQs have their own identities, options, keys and history. No subjective rows are remapped. */
final class CAFCC_MCQ {
    const TABLES=array('questions','scenarios','tags','members','personal','sessions','attempts','tests','jobs');
    public static function table($kind){if(!in_array($kind,self::TABLES,true))throw new InvalidArgumentException('Unknown MCQ table.');global $wpdb;return $wpdb->prefix.'cafcc_mcq_'.$kind;}
    public static function migrate(){
        global $wpdb;$schemas=array(
            'questions'=>"id bigint(20) unsigned NOT NULL AUTO_INCREMENT, stable_id varchar(120) NOT NULL, occurrence_key varchar(120) NOT NULL, identity_hash varchar(64) NOT NULL, revision bigint(20) unsigned NOT NULL DEFAULT 1, publication_status varchar(16) NOT NULL DEFAULT 'draft', subject_code varchar(16) NOT NULL, source_type varchar(32) NOT NULL, exam_attempt varchar(80) NOT NULL, mtp_series varchar(40) NOT NULL, source_hash varchar(64) NOT NULL, source_key varchar(120) NOT NULL, question_number varchar(40) NOT NULL, edition_key varchar(120) NOT NULL, scenario_id bigint(20) unsigned NOT NULL DEFAULT 0, question_html longtext NOT NULL, options_json longtext NOT NULL, correct_json text NOT NULL, key_policy varchar(24) NOT NULL, key_verified tinyint(1) NOT NULL DEFAULT 0, permission_required tinyint(1) NOT NULL DEFAULT 1, rights_grant_id bigint(20) unsigned NOT NULL DEFAULT 0, rights_grant_revision bigint(20) unsigned NOT NULL DEFAULT 0, publication_fingerprint varchar(64) NOT NULL DEFAULT '', search_text longtext NOT NULL, payload longtext NOT NULL, modified_at datetime NOT NULL, PRIMARY KEY  (id), UNIQUE KEY stable_id (stable_id), UNIQUE KEY identity_hash (identity_hash), UNIQUE KEY occurrence_key (occurrence_key), KEY public_source (publication_status,subject_code,source_type,exam_attempt,id), KEY public_series (publication_status,mtp_series,id), KEY source_hash (source_hash)",
            'scenarios'=>"id bigint(20) unsigned NOT NULL AUTO_INCREMENT, scenario_key varchar(120) NOT NULL, source_hash varchar(64) NOT NULL, revision bigint(20) unsigned NOT NULL DEFAULT 1, body_html longtext NOT NULL, evidence longtext NOT NULL, PRIMARY KEY  (id), UNIQUE KEY scenario_key (scenario_key)",
            'tags'=>"id bigint(20) unsigned NOT NULL AUTO_INCREMENT, mcq_id bigint(20) unsigned NOT NULL, label varchar(190) NOT NULL, normalised varchar(190) NOT NULL, kind varchar(24) NOT NULL, origin varchar(40) NOT NULL, evidence text NOT NULL, PRIMARY KEY  (id), UNIQUE KEY question_tag (mcq_id,normalised), KEY search_tag (normalised,mcq_id), KEY kind_tag (kind,normalised,mcq_id)",
            'members'=>"package_id bigint(20) unsigned NOT NULL, mcq_id bigint(20) unsigned NOT NULL, PRIMARY KEY  (package_id,mcq_id), KEY question_packages (mcq_id,package_id)",
            'personal'=>"user_id bigint(20) unsigned NOT NULL, mcq_id bigint(20) unsigned NOT NULL, bookmark tinyint(1) NOT NULL DEFAULT 0, tags text NOT NULL, updated_at datetime NOT NULL, PRIMARY KEY  (user_id,mcq_id)",
            'sessions'=>"id bigint(20) unsigned NOT NULL AUTO_INCREMENT, session_key varchar(40) NOT NULL, user_id bigint(20) unsigned NOT NULL, mcq_id bigint(20) unsigned NOT NULL, content_revision bigint(20) unsigned NOT NULL, status varchar(16) NOT NULL DEFAULT 'open', started_at datetime NOT NULL, attempt_id bigint(20) unsigned NOT NULL DEFAULT 0, selection_json text NOT NULL, PRIMARY KEY  (id), UNIQUE KEY session_key (session_key), KEY owned_question (user_id,mcq_id,status,id)",
            'attempts'=>"id bigint(20) unsigned NOT NULL AUTO_INCREMENT, user_id bigint(20) unsigned NOT NULL, mcq_id bigint(20) unsigned NOT NULL, occurrence_key varchar(120) NOT NULL, attempt_number int unsigned NOT NULL, selection_json text NOT NULL, is_correct tinyint(1) NOT NULL, active_seconds int unsigned NOT NULL, content_revision bigint(20) unsigned NOT NULL, key_fingerprint varchar(64) NOT NULL, test_id bigint(20) unsigned NOT NULL DEFAULT 0, created_at datetime NOT NULL, PRIMARY KEY  (id), UNIQUE KEY owned_attempt (user_id,mcq_id,attempt_number), KEY student_date (user_id,created_at,id), KEY question_owner (mcq_id,user_id,id), KEY owned_test (user_id,test_id)",
            'tests'=>"id bigint(20) unsigned NOT NULL AUTO_INCREMENT, test_key varchar(40) NOT NULL, request_key varchar(40) NOT NULL, user_id bigint(20) unsigned NOT NULL, status varchar(16) NOT NULL DEFAULT 'open', started_at datetime NOT NULL, ends_at datetime NOT NULL, submitted_at datetime DEFAULT NULL, payload longtext NOT NULL, result longtext NOT NULL, PRIMARY KEY  (id), UNIQUE KEY test_key (test_key), UNIQUE KEY owned_request (user_id,request_key), KEY active_tests (user_id,status,id)",
            'jobs'=>"id bigint(20) unsigned NOT NULL AUTO_INCREMENT, job_key varchar(40) NOT NULL, owner_id bigint(20) unsigned NOT NULL, action_name varchar(24) NOT NULL, phase varchar(24) NOT NULL, cursor_position int unsigned NOT NULL DEFAULT 0, payload longtext NOT NULL, report longtext NOT NULL, confirmed_at datetime DEFAULT NULL, created_at datetime NOT NULL, PRIMARY KEY  (id), UNIQUE KEY job_key (job_key), KEY owned_job (owner_id,id)"
        );
        foreach($schemas as $kind=>$columns){$columns=preg_replace('/,\s+(?=[A-Za-z_])/',",\n",$columns);$t=self::table($kind);dbDelta("CREATE TABLE $t ($columns) ENGINE=InnoDB ".$wpdb->get_charset_collate().';');preg_match_all('/^\s*([a-z_]+) (?:bigint|varchar|int|tinyint|datetime|longtext|text)/m',$columns,$m);$actual=$wpdb->get_col("SHOW COLUMNS FROM $t");if(!$actual||array_diff($m[1],$actual))return CAFCC_Repository::error('MCQ migration is incomplete. Existing data is retained.',503);}
        return true;
    }
    public static function get($id,$lock=false){global $wpdb;$r=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.self::table('questions').' WHERE id=%d'.($lock?' FOR UPDATE':''),$id),ARRAY_A);if($r){$r['data']=json_decode($r['payload'],true);$r['options']=json_decode($r['options_json'],true);$r['correct']=json_decode($r['correct_json'],true);}return $r;}
    public static function clean($d){
        if(!is_array($d))return CAFCC_Repository::error('Invalid MCQ record.');$keys=array('stable_id','source_occurrence_id','subject_code','source_type','exam_attempt','mtp_series','issue_period','edition_key','scheme','section','reference','source_key','source_hash','official_url','question_page','question_location','question_html','question_checks','question_structure','options','scenario','answer','correct_options','key_policy','key_verified','explanation_html','tags','exceptions','review_status','academic_approval','extraction_confidence','review_notes');if(array_diff(array_keys($d),$keys))return CAFCC_Repository::error('Unexpected MCQ fields.');
        foreach(array('stable_id'=>120,'source_occurrence_id'=>120,'source_key'=>120,'edition_key'=>120,'section'=>120,'reference'=>40,'exam_attempt'=>80,'mtp_series'=>40,'scheme'=>80,'issue_period'=>80) as $key=>$limit){if(!is_string($d[$key]??'')||strlen($d[$key]??'')>$limit)return CAFCC_Repository::error('Invalid MCQ identity '.$key);$d[$key]=sanitize_text_field($d[$key]??'');}
        if(!preg_match('/^[A-Za-z0-9_.:-]{2,120}$/D',$d['stable_id'])||!preg_match('/^[A-Za-z0-9_.:-]{2,120}$/D',$d['source_occurrence_id'])||!preg_match('/^[a-f0-9]{64}$/D',$d['source_hash']??'')||!in_array($d['subject_code']??'',array('FR','AFM','AUDIT','DT','IDT','IBS'),true)||!in_array($d['source_type']??'',array('rtp','mtp','exam','other'),true)||!$d['exam_attempt']||!$d['reference']||!CAFCC_Sources::public_url($d['official_url']??''))return CAFCC_Repository::error('Identify the exact MCQ source, attempt, reference and PDF hash.');
        if($d['source_type']==='mtp'&&!$d['mtp_series'])return CAFCC_Repository::error('MTP series is required.');
        foreach(array('question_html','explanation_html') as $key){$s=$d[$key]??'';if(!is_string($s)||strlen($s)>300000)return CAFCC_Repository::error('MCQ content is too large.');if(CAFCC_Bank_DB::private_reference($s))return CAFCC_Repository::error('Keep Drive references in the source register, outside question/answer prose.');$d[$key]=CAFCC_Practice::html($s);}
        if(!is_int($d['question_page']??null)||$d['question_page']<1||$d['question_page']>10000)return CAFCC_Repository::error('Record the MCQ PDF page.');
        if(!is_array($d['options']??null)||!array_is_list($d['options'])||count($d['options'])>10)return CAFCC_Repository::error('Use the source options, up to ten.');$seen=array();foreach($d['options'] as &$o){if(!is_array($o)||!preg_match('/^[A-J]$/D',$o['id']??'')||isset($seen[$o['id']])||!is_string($o['html']??null)||strlen($o['html'])>100000)return CAFCC_Repository::error('Invalid or repeated MCQ option.');$seen[$o['id']]=true;if(CAFCC_Bank_DB::private_reference($o['html']))return CAFCC_Repository::error('Private Drive references cannot appear in options.');$o['html']=CAFCC_Practice::html($o['html']);}unset($o);
        $correct=$d['correct_options']??array();if(!is_array($correct)||!array_is_list($correct)||array_diff($correct,array_keys($seen)))return CAFCC_Repository::error('Key refers to an absent option.');$d['correct_options']=array_values(array_unique($correct));sort($d['correct_options']);
        if(!in_array($d['key_policy']??'',array('single','any_of','all_of','needs_owner_decision'),true)||!is_bool($d['key_verified']??false))return CAFCC_Repository::error('Identify the key verification and selection policy.');
        foreach(array('tags','exceptions') as $key){if(!is_array($d[$key]??array())||!array_is_list($d[$key]??array())||count($d[$key]??array())>100)return CAFCC_Repository::error('Invalid MCQ '.$key);$d[$key]=$d[$key]??array();}
        foreach($d['exceptions'] as &$e){if(!is_string($e)||strlen($e)>190)return CAFCC_Repository::error('Invalid MCQ exception.');$e=sanitize_text_field($e);}unset($e);
        if(!is_array($d['answer']??null))return CAFCC_Repository::error('Include the exact answer-key identity.');
        if(!empty($d['scenario'])){if(!is_array($d['scenario'])||!preg_match('/^[A-Za-z0-9_.:-]{2,120}$/D',$d['scenario']['key']??'')||($d['scenario']['source_hash']??'')!==$d['source_hash']||!is_string($d['scenario']['html']??null)||strlen($d['scenario']['html'])>300000)return CAFCC_Repository::error('Shared facts must belong to this PDF.');if(CAFCC_Bank_DB::private_reference($d['scenario']['html']))return CAFCC_Repository::error('Private Drive references cannot appear in shared facts.');$d['scenario']['html']=CAFCC_Practice::html($d['scenario']['html']);}
        $d['review_status']='needs_review';$d['academic_approval']=false;$d['review_notes']=sanitize_textarea_field($d['review_notes']??'');return $d;
    }
    public static function identity($d){return hash('sha256',implode('|',array($d['source_hash'],$d['section'],$d['reference'])));}
    public static function tags($id){global $wpdb;return $wpdb->get_results($wpdb->prepare('SELECT label,normalised,kind,origin,evidence FROM '.self::table('tags').' WHERE mcq_id=%d ORDER BY id',$id),ARRAY_A);}
    public static function save_tags($r){
        global $wpdb;$d=$r['data'];$v=array('subject_code'=>$d['subject_code'],'classification'=>array(),'rich_content'=>array('question'=>array('body_html'=>$d['question_html']),'answer'=>array('body_html'=>$d['explanation_html']??'')));$manual=array();foreach($d['tags'] as $tag){$label=is_array($tag)?($tag['label']??''):$tag;if(!is_string($label)||strlen($label)>190)return CAFCC_Repository::error('Use short academic labels.');$manual[]=$label;}$tags=CAFCC_Search_Tags::suggest($v,$manual);if(is_wp_error($tags))return $tags;$wpdb->delete(self::table('tags'),array('mcq_id'=>$r['id']));foreach($tags as $tag){unset($tag['academic_verification']);if($tag['origin']==='owner_correction')$tag['origin']='imported_provisional';if(CAFCC_Standards::entry($tag['label']))$tag['kind']='standard';if(false===$wpdb->insert(self::table('tags'),array_merge($tag,array('mcq_id'=>$r['id']))))return CAFCC_Repository::error('Cannot retain MCQ search tags.',500);}return true;
    }
    public static function import($payload){
        if(is_wp_error($e=CAFCC_Studio::admin()))return $e;if(!is_array($payload)||array_diff(array_keys($payload),array('format','records'))||($payload['format']??'')!=='CAFCC-MCQ-DRAFTS-1'||!is_array($payload['records'])||!array_is_list($payload['records'])||count($payload['records'])>100)return CAFCC_Repository::error('Use a CAFCC-MCQ-DRAFTS-1 item of at most 100 records.');
        return CAFCC_Academic::transaction(function()use($payload){global $wpdb;$out=array('created'=>0,'retained'=>0,'conflicts'=>array());foreach($payload['records'] as $raw){$d=self::clean($raw);if(is_wp_error($d))return $d;$identity=self::identity($d);$old=$wpdb->get_row($wpdb->prepare('SELECT id,stable_id,identity_hash,occurrence_key,payload FROM '.self::table('questions').' WHERE stable_id=%s OR identity_hash=%s OR occurrence_key=%s FOR UPDATE',$d['stable_id'],$identity,$d['source_occurrence_id']),ARRAY_A);if($old){if($old['stable_id']!==$d['stable_id']||$old['identity_hash']!==$identity||$old['occurrence_key']!==$d['source_occurrence_id'])return CAFCC_Repository::error('MCQ stable ID conflicts with a different occurrence. No remapping performed.',409);$out['retained']++;if($old['payload']!==wp_json_encode($d))$out['conflicts'][]=array('stable_id'=>$d['stable_id'],'message'=>'Existing correction retained; import does not overwrite it.');continue;}
                $sid=0;if(!empty($d['scenario'])){$s=$d['scenario'];$sid=(int)$wpdb->get_var($wpdb->prepare('SELECT id FROM '.self::table('scenarios').' WHERE scenario_key=%s FOR UPDATE',$s['key']));if($sid){$body=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.self::table('scenarios').' WHERE id=%d',$sid),ARRAY_A);if($body['source_hash']!==$d['source_hash']||$body['body_html']!==$s['html'])return CAFCC_Repository::error('Existing shared facts differ. Resolve the source-specific correction before importing dependent MCQs.',409);}else{if(false===$wpdb->insert(self::table('scenarios'),array('scenario_key'=>$s['key'],'source_hash'=>$d['source_hash'],'body_html'=>$s['html'],'evidence'=>wp_json_encode($s))))return CAFCC_Repository::error('Cannot retain shared MCQ facts.',500);$sid=$wpdb->insert_id;}}
                $row=array('stable_id'=>$d['stable_id'],'occurrence_key'=>$d['source_occurrence_id'],'identity_hash'=>$identity,'subject_code'=>$d['subject_code'],'source_type'=>$d['source_type'],'exam_attempt'=>$d['exam_attempt'],'mtp_series'=>$d['mtp_series'],'source_hash'=>$d['source_hash'],'source_key'=>$d['source_key'],'question_number'=>$d['reference'],'edition_key'=>$d['edition_key'],'scenario_id'=>$sid,'question_html'=>$d['question_html'],'options_json'=>wp_json_encode($d['options']),'correct_json'=>wp_json_encode($d['correct_options']),'key_policy'=>$d['key_policy'],'key_verified'=>$d['key_verified']?1:0,'search_text'=>CAFCC_Search_Tags::normalise(wp_strip_all_tags($d['question_html'].' '.($d['scenario']['html']??''))),'payload'=>wp_json_encode($d),'modified_at'=>current_time('mysql',true));if(false===$wpdb->insert(self::table('questions'),$row))return CAFCC_Repository::error('Cannot retain MCQ draft.',500);$r=self::get($wpdb->insert_id);$tagged=self::save_tags($r);if(is_wp_error($tagged)||!CAFCC_Bank_DB::audit_master('mcq_created',$r['id'],null,$r))return CAFCC_Repository::error('Cannot retain MCQ import audit.',500);$out['created']++;}return $out;});
    }
    public static function context($d){$v=$d;$a=$d['answer'];$v['answer']=array('official_url'=>$a['official_url']??'','source_hash'=>$a['source_hash']??'');return $v;}
    public static function quality($r){
        $d=$r['data'];$b=array();$w=$d['exceptions'];if(!CAFCC_Owner::html_integrity($r['question_html']))$b[]='Question text or table structure needs correction.';foreach($r['options'] as $o)if(!CAFCC_Owner::html_integrity($o['html']))$b[]='Option '.$o['id'].' is incomplete or structurally invalid.';if(count($r['options'])<2)$b[]='Source options are incomplete.';
        if(!empty($d['answer']['key_evidence']['no_correct_option'])&&empty($r['correct']))$b[]='Official key: No correct option. Retained for unscored review; official marking guidance is required before scored practice.';
        elseif(!$r['key_verified']||!$r['correct']||!in_array($r['key_policy'],array('single','any_of','all_of'),true)||($r['key_policy']==='single'&&count($r['correct'])!==1))$b[]='Exact answer key / selection policy needs correction.';
        $a=$d['answer'];if(($a['subject_code']??'')!==$d['subject_code']||($a['source_type']??$d['source_type'])!==$d['source_type']||($a['exam_attempt']??$d['exam_attempt'])!==$d['exam_attempt']||($a['mtp_series']??$d['mtp_series'])!==$d['mtp_series']||($a['question_reference']??'')!==$d['reference']||($a['question_source_hash']??'')!==$d['source_hash']||!preg_match('/^[a-f0-9]{64}$/D',$a['source_hash']??'')||empty($a['page'])||empty($a['key_evidence']))$b[]='Question and answer-key identity do not match exactly.';$printed=$a['key_evidence']['correct_options']??null;if(!is_array($printed)||array_values($printed)!==$r['correct']||(int)($a['key_evidence']['page']??0)!==(int)($a['page']??0))$b[]='Stored key differs from its source evidence.';
        if(empty($d['question_checks']['passed']))$b[]='Question numerical transcription check failed.';foreach($r['options'] as $o)if(empty($o['checks']['passed']))$b[]='Option '.$o['id'].' transcription check failed.';
        if(!empty($d['scenario'])){if(empty($d['scenario']['checks']['passed']))$b[]='Common facts transcription needs correction.';global $wpdb;$s=$wpdb->get_row($wpdb->prepare('SELECT body_html,source_hash FROM '.self::table('scenarios').' WHERE id=%d',$r['scenario_id']),ARRAY_A);if(!$s||$s['source_hash']!==$d['source_hash']||$s['body_html']!==$d['scenario']['html'])$b[]='Shared scenario revision changed.';}
        foreach($d['exceptions'] as $e)if(preg_match('/requires_owner_decision|question_range_requires_review|missing_|incomplete|transcription|numerical|conflict|ambiguous/', $e))$b[]='Source review: '.$e;
        $context=self::context($d);$grant=CAFCC_Owner::grant($context);if(!$grant||!CAFCC_Rights::covers($grant['id'],$context,'answer'))$b[]='No current source-wide permission covers this question and key.';
        foreach(array('question','answer') as $kind){$x=$kind==='question'?$d:$a;$source=CAFCC_Sources::find_url($x['official_url']??'',$x['source_hash']??'');if(!$source)$b[]='Registered '.$kind.' PDF identity is missing.';else{$s=$source['data'];foreach(array('subject_code','source_type','exam_attempt','mtp_series') as $k)if($s[$k]!==$d[$k])$b[]='Registered '.$kind.' source context differs.';if($s['technical_state']!=='pdf_checked'||$s['selection_state']!=='owner_verified'||$source['source_hash']!==$x['source_hash']||!in_array($s['role'],array($kind==='question'?'questions':'answers','questions_and_answers'),true))$b[]='Registered '.$kind.' PDF needs the correct role and integrity checks.';}}
        $ed=CAFCC_Academic::by_key('editions',$d['edition_key']);if(!$ed||!CAFCC_Owner::attempt_matches($ed,$d['exam_attempt']))$b[]='Applicable source edition needs correction.';
        return array('blocks'=>array_values(array_unique($b)),'warnings'=>$w,'grant'=>$grant,'academic_verification'=>'not_independently_verified');
    }
    public static function fingerprint($r){return hash('sha256',wp_json_encode(array($r['revision'],$r['question_html'],$r['options_json'],$r['correct_json'],$r['key_policy'],$r['payload'],$r['scenario_id'])));}
    public static function guard($alias='m'){return "$alias.publication_status='published' AND $alias.key_verified=1 AND $alias.publication_fingerprint<>''".CAFCC_Rights::public_guard($alias);}
    public static function visible($r){return $r&&$r['publication_status']==='published'&&$r['key_verified']&&hash_equals($r['publication_fingerprint'],self::fingerprint($r))&&CAFCC_Rights::covers($r['rights_grant_id'],self::context($r['data']),'question')&&CAFCC_Rights::covers($r['rights_grant_id'],self::context($r['data']),'answer')&&(int)CAFCC_Rights::get($r['rights_grant_id'])['revision']===(int)$r['rights_grant_revision'];}
    public static function citation($r){$d=$r['data'];$public=CAFCC_Public_Sources::find($r['source_hash'],'question');return array('label'=>implode(' · ',array_filter(array(strtoupper($d['source_type']).($d['mtp_series']?' '.$d['mtp_series']:''),$d['subject_code'],$d['exam_attempt'],'Q'.$d['reference']))),'url'=>$public['url']??$d['official_url'],'page'=>(int)$d['question_page'],'owner_public_copy'=>(bool)$public,'page_jump_supported'=>!$public,'attribution'=>'ICAI source acknowledgment · owner-authorised copy');}
    public static function sync_package($id){global $wpdb;$items=$wpdb->get_results($wpdb->prepare('SELECT payload FROM '.CAFCC_Package::items_table()." WHERE package_id=%d AND kind='mcqs' AND status='applied'",$id),ARRAY_A);$count=0;foreach($items as $item)foreach(json_decode($item['payload'],true)['records'] as $d){$mid=(int)$wpdb->get_var($wpdb->prepare('SELECT id FROM '.self::table('questions').' WHERE stable_id=%s AND identity_hash=%s',$d['stable_id'],self::identity($d)));if($mid){if(false===$wpdb->query($wpdb->prepare('INSERT IGNORE INTO '.self::table('members').' (package_id,mcq_id) VALUES (%d,%d)',$id,$mid)))return CAFCC_Repository::error('MCQ package membership checkpoint failed.',500);$count++;}}if($count)update_option('cafcc_current_mcq_package',$id,false);return array('record_kind'=>'mcq','members'=>$count);}
}
